"""Wizard model discovery and viewport tests (simulated provider catalogs)."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import shutil,os
ROOT=Path(__file__).resolve().parents[1]
mock='''window.calls=[];window.fetch=async(url,opts)=>{calls.push(String(url));let data=String(url).includes('groq')?{data:[{id:'whisper-large-v3-turbo'},{id:'text-model'}]}:String(url).endsWith('/projects')?{projects:[{project_id:'test-project'}]}:{stt:[{name:'nova-3',canonical_name:'nova-3',batch:true}],tts:[{name:'voice'}]};return new Response(JSON.stringify(data),{status:200})}'''
html=(ROOT/'index.html').read_text().replace('<link rel="stylesheet" href="studio.css">','<style>'+(ROOT/'studio.css').read_text()+'</style>').replace('<script src="studio.js" defer></script>','<script>'+mock+'</script><script>'+(ROOT/'studio.js').read_text()+'</script>')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or shutil.which('chromium'),args=['--no-sandbox']);page=b.new_page(viewport={'width':1366,'height':768});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.set_content(html)
 def viewport():assert page.evaluate('document.documentElement.scrollHeight<=innerHeight && document.documentElement.scrollWidth<=innerWidth')
 viewport();page.screenshot(path='/tmp/wizard-welcome.png');page.locator('#welcomeStart').click();viewport();page.screenshot(path='/tmp/wizard-connect.png');page.locator('#apiKey').fill('ambiguous_key_123456789');page.wait_for_timeout(900);assert page.evaluate('calls.length')==0
 page.locator('#apiKey').fill('sk-generic-example_123456789');page.wait_for_timeout(900);assert page.evaluate('calls.length')==0;assert 'Paste a full key' in page.locator('#connectionStatus').inner_text()
 page.locator('#apiKey').fill('gsk_mock_123456789012345');page.wait_for_selector('#screen-3',state='visible');assert page.evaluate('opts().groqModels')==['whisper-large-v3-turbo'];viewport();page.screenshot(path='/tmp/wizard-workspace.png');print('desktop setup scroll delta',page.locator('.setup').evaluate('e=>e.scrollHeight-e.clientHeight'))
 page.locator('#changeConnection').click();page.locator('#providerSelect').select_option('deepgram');page.locator('#apiKey').fill('deepgram_mock_123456789');page.wait_for_selector('#screen-3',state='visible');assert 'Deepgram' in page.locator('#activeConnection').inner_text();assert 'Groq' in page.locator('#activeConnection').inner_text();page.locator('#linkTab').click();viewport();assert page.locator('#helperShortcut').is_visible();page.locator('#helperShortcut').click();assert page.locator('#helperSettings').evaluate('e=>e.open');page.locator('#continueStudio').click();viewport()
 page.set_viewport_size({'width':390,'height':844});viewport();assert page.locator('#screen-3').is_visible();assert not errors,errors;print('Wizard: viewport, auto Groq discovery, ambiguous-key isolation, Deepgram selection, dual provider, helper settings and mobile — passed');b.close()
